const months=d=>new Date(d+'T00:00:00Z').toLocaleDateString('de-DE',{month:'long',year:'numeric',timeZone:'UTC'});
const colors=['#1f77b4','#ff7f0e','#2ca02c','#d62728','#9467bd','#8c564b','#e377c2','#7f7f7f','#bcbd22','#17becf','#658cc0','#9b6397','#cc6c64','#7f9654','#5f8492','#a58642','#535c9c','#b87593','#848f86','#9172b3'];
